-- ============================================================
-- Landing CMU — 12 poemas do Yama to Mizu, 1 por mês
-- ------------------------------------------------------------
-- Substitui os 60 poemas do seed original: só 12 deles existiam no Yama to
-- Mizu. Com 3 poemas por estação, escolherDoPool (landing.js) mostra sempre o
-- mesmo poema em cada mês: posição 0/1/2 do pool = 1º/2º/3º mês da estação.
-- Texto em data/poetry/yama_to_mizu.json (yama_number = número do poema).
-- ============================================================

update public.landing_config
   set season_pools = '{"verao":[{"title":"Expansão da Alma","original":"風薫り　青葉光れる初夏の　庭に下りたてば胸のひろぎぬ","romaji":"Kaze kaori / aoba hikareru / hatsunatsu no / niwa ni oritateba / mune no hiroginu","translation":"O vento é perfumado, as folhas verdes resplandecem;\nAo descer ao jardim no início do verão,\nMeu peito se dilata.","kigo":"Verão","meses":[12],"yama_number":9},{"title":"O Perfume da Maré","original":"松かげの　汀の砂に潮の香を　したしみながら少時やすらう","romaji":"Matsukage no / migiwa no suna ni / shio no ka o / shitashiminagara / shibashi yasurau","translation":"À sombra dos pinheiros, na areia da praia...\nApreciando o perfume da maré,\ndescanso por um momento.","kigo":"Verão","meses":[1],"yama_number":179},{"title":"O Arco-íris Súbito","original":"木々の葉を　鳴らしてゆきし白雨の　はや美しき虹となりけり","romaji":"Kiginoha o / narashite yukishi shirasame no / haya uruwashiki niji to narikeri","translation":"Aquele aguaceiro, que passou fazendo soar as folhas das árvores...\nEis que já se transformou\nEm um belo arco-íris.","kigo":"Verão","meses":[2],"yama_number":915}],"outono":[{"title":"A Correnteza Subterrânea","original":"いまだしも　暑さのこれどその底に　秋のけはいのうすら流るる","romaji":"Imadashimo / atsusa nokoredo sono soko ni / aki no kehai no usura nagaruru","translation":"Embora o calor ainda persista...\nLá no fundo,\nFlui, tênue, a presença do Outono.","kigo":"Outono","meses":[3],"yama_number":926},{"title":"Pássaros Migratórios","original":"秋空の　かがやかしげよ渡り鳥　羽いそがしげに三つ四つゆくも","romaji":"Akizora no / kagayakashige yo wataridori / hane isogashige ni mitsu yotsu yuku mo","translation":"Quão resplandecente é o Céu de Outono!\nCruzando-o, três ou quatro aves migratórias passam,\nBatendo suas asas com pressa.","kigo":"Outono","meses":[4],"yama_number":965},{"title":"Os Caquis Maduros","original":"みな黄ばむ　山裾村に幾本の　柿の木みえてみな熟れ赤き","romaji":"Mina kibamu / yamasuso mura ni / ikuhon no / kaki no ki miete / mina ureakaki","translation":"Tudo amarela...\nNo sopé da montanha, na vila,\nVejo árvores de Caqui:\nTodos os frutos estão rubros e maduros.","kigo":"Outono","meses":[5],"yama_number":225}],"inverno":[{"title":"O Som da Cozinha no Crepúsculo","original":"みぢか日に　はや小暗かり厨べに　夕餉の仕度か物の音する","romaji":"Mijikabi ni / haya ogurakari kuriyabe ni / yūge no shitaku ka mono no oto suru","translation":"Nestes dias curtos de inverno, logo escurece...\nVindos da cozinha,\nOuvem-se ruídos: seria o preparo do jantar?","kigo":"Inverno","meses":[6],"yama_number":986},{"title":"Pardais na Geada","original":"霜ふかき　朝なりけり寒雀　うらさやがしく小庭とびちる","romaji":"Shimo fukaki / ashita narikeri / kansuzume / urasayagashiku / saniwa tobichiru","translation":"É uma manhã de geada profunda...\nOs Pardais do Frio voam dispersos pelo pequeno jardim,\nCom um ruído fresco e vivaz.","kigo":"Inverno","meses":[7],"yama_number":1046},{"title":"A Flor Secreta da Nespereira","original":"夕まけて　冬陽のとどく庭隅に　いとひそけくもびわの花咲く","romaji":"Yūmakete / fuyubi no todoku niwasumi ni / ito hisokeku mo biwa no hana saku","translation":"Aproximando-se a noite...\nNum canto do jardim onde o sol de inverno ainda toca,\nDe forma tão secreta e discreta,\nA Nespereira abre suas flores.","kigo":"Inverno","meses":[8],"yama_number":1022}],"primavera":[{"title":"A Primavera Interior","original":"春は先づ　人の心に立ちそむか　昨日と同じ寒風ふけども","romaji":"Haru wa mazu / hito no kokoro ni tachisomu ka / kinō to onaji samukaze fukedomo","translation":"A Primavera começa primeiro\ndentro do coração humano?\nO mesmo vento gélido de ontem\ncontinua a soprar.","kigo":"Primavera","meses":[9],"yama_number":1183},{"title":"A Contemplação da Borboleta","original":"蝶一つ　わが辺をすぎぬひらひらと　花にかくらうまでを立ちにつ","romaji":"Chō hitotsu / waga he o suginu / hirahira to / hana ni kakurau / made o tachinitsu","translation":"Uma borboleta, só, por mim esvoaça...\nE, até que entre as flores se esconda,\nde pé, eu a acompanho.","kigo":"Primavera","meses":[10],"yama_number":831},{"title":"O Verde que Arde","original":"うららけき　日條に雨後の草の原　緑さやかに萌えたぎろえる","romaji":"Urarakeki / hisuji ni ugo no kusanohara / midori sayaka ni moetagiroeru","translation":"Sob os raios radiantes do sol,\nNo campo de relva após a chuva,\nO verde nítido parece arder e ferver.","kigo":"Primavera","meses":[11],"yama_number":1189}]}'::jsonb,
       updated_at = now()
 where id = 1;
